    (
                type = 'datacategory_sql'
            OR type = 'servicecontacts_datacategory_sql'
            OR type = 'entitytype_datacategory_sql'
            OR type = 'cashbillsourcebill_datacategory_sql'
            OR type = 'sendcashbillsourcebill_datacategory_sql'
            OR type = 'budget_datacategory_sql'
        )
  AND actions = 'add' and (related_advanceset is null or related_advanceset='');
