CREATE TABLE IF NOT EXISTS `ld_holiday` (
    `holidayid` int(11) NOT NULL,
    `holidayno` varchar(255) DEFAULT NULL,
    `holiday_title` varchar(100) COMMENT 'Custom holiday name',
    `holiday_name` varchar(100) COMMENT 'Holiday name',
    `holiday_date` date COMMENT 'Date',
    `wheatherholidays` boolean COMMENT 'The date is',
    `holiday_type` text COMMENT 'Holiday type',
    `description` text COMMENT 'Holiday type',
    `smownerid` Int(4) NOT NULL,
    `smcreatorid` Int(4),
    `createdtime` datetime ,
    `modifiedby` Int(4),
    `modifiedtime` datetime,
    `approvestatus` Varchar(50),
    `approvetime` Datetime,
    `approveby` Int(4),
    `currentapprover` text,
    `latestpushtime` Datetime,
    `Advance_stage` Varchar(100),
    `exchtime` Datetime,
    `exchmsg` text,
    `team_memberid` text,
    `tag` text,
    `Print_times` int(4),
    `approvesubmitter` int(4),
    `approveurgent` Varchar(100),
    `approveexpediting` Varchar(100) ,
    `Kis_id` Int(4) ,
    `Kis_no` Varchar(50) ,
    PRIMARY KEY (`holidayid`)
) ENGINE = INNODB DEFAULT CHARSET = utf8;
