SET @tmp_update = (select 1 from ld_settings_blocks where label='EnterpriseLogs');

SET @sequence = (SELECT sequence from ld_settings_blocks WHERE label='LBL_INTERFACE_SETTINGS');
SET @blockid = (SELECT max(blockid) from ld_settings_blocks);
UPDATE ld_settings_blocks set sequence =
CASE
	WHEN @tmp_update = 1 THEN (sequence)
	ELSE sequence + 1
END
where sequence > @sequence;

INSERT INTO ld_settings_blocks(blockid,label,sequence,active)
SELECT @blockid+1,'EnterpriseLogs',@sequence+1,0 FROM DUAL
where not exists(select 1 from ld_settings_blocks where label='EnterpriseLogs');
delimiter;

select blockid into @blockid from ld_settings_blocks where label='EnterpriseLogs';
update ld_settings_field set blockid = @blockid , sequence = 1 where `name` = 'LBL_LOGIN_HISTORY_DETAILS' and blockid = 5;

select max(sequence) into @sequence from ld_settings_field where blockid = @blockid;
select max(fieldid) + 1 into @fieldid from ld_settings_field;
insert into ld_settings_field(fieldid,blockid,name,iconpath,description,linkto,sequence,active)
select  @fieldid,@blockid,'OperationLogs','','OperationLogs','index.php?module=Settings&action=OperationLogs&parenttab=Settings',@sequence+1,0 from dual
where not exists(select 1 from ld_settings_field where name='OperationLogs');
delimiter;

select max(fieldid) + 1 into @fieldid from ld_settings_field;
insert into ld_settings_field(fieldid,blockid,name,iconpath,description,linkto,sequence,active)
select  @fieldid,@blockid,'ImportExportLogs','','导入导出日志','index.php?module=Settings&action=OperationLogs&parenttab=Settings&logtype=ImportExport',@sequence+1,0 from dual
where not exists(select 1 from ld_settings_field where name='ImportExportLogs');
