CREATE TABLE IF NOT EXISTS `ld_crmlog_entity` (
    `id` BIGINT(20) NOT NULL AUTO_INCREMENT,
    `userid` int(20) NOT NULL,
    `actiontype` varchar(100) NOT NULL,
    `module` varchar(100) DEFAULT NULL ,
    `operationtime` datetime DEFAULT NULL,
    `relatedid` int(20) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
delimiter;

CREATE TABLE IF NOT EXISTS `ld_crmlog_edit` (
    `id` int(20) NOT NULL,
    `userid` int(20) NOT NULL,
    `action` varchar(100) NOT NULL,
    `module` varchar(100) DEFAULT NULL ,
    `crmid` int(20) DEFAULT NULL,
    `operationdetails` text(0) DEFAULT NULL,
    `operationtime` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
delimiter;

CREATE TABLE IF NOT EXISTS `ld_crmlog_create` (
    `id` int(20) NOT NULL,
    `userid` int(20) NOT NULL,
    `action` varchar(100) NOT NULL,
    `module` varchar(100) DEFAULT NULL ,
    `crmid` int(20) DEFAULT NULL,
    `operationdetails` text(0) DEFAULT NULL,
    `operationtime` datetime DEFAULT NULL,
    `frommodule` varchar(100) DEFAULT NULL ,
    `fromcrmid` int(20) DEFAULT NULL ,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
delimiter;

CREATE TABLE IF NOT EXISTS `ld_crmlog_share` (
    `id` int(20) NOT NULL,
    `userid` int(20) NOT NULL,
    `action` varchar(100) NOT NULL,
    `module` varchar(100) DEFAULT NULL ,
    `crmid` int(20) DEFAULT NULL,
    `operationdetails` text(0) DEFAULT NULL,
    `operationtime` datetime DEFAULT NULL,
    `shareto_userids` text(0) DEFAULT NULL ,
    `remove_userids` text(0) DEFAULT NULL ,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
delimiter;

CREATE TABLE IF NOT EXISTS `ld_crmlog_delete` (
    `id` int(20) NOT NULL,
    `userid` int(20) NOT NULL,
    `action` varchar(100) NOT NULL,
    `actiontype` varchar(100) NOT NULL,
    `module` varchar(100) DEFAULT NULL ,
    `crmid` int(20) DEFAULT NULL,
    `operationdetails` text(0) DEFAULT NULL,
    `operationtime` datetime DEFAULT NULL,
    `mergedcrmids` text(0) DEFAULT NULL ,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
delimiter;

CREATE TABLE IF NOT EXISTS `ld_crmlog_deletedrecords` (
    `id` int(20) NOT NULL AUTO_INCREMENT,
    `crmid` int(20) NOT NULL,
    `keyinfo` text(0) DEFAULT NULL ,
    `hyperlink_content` text(0) DEFAULT NULL ,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
delimiter;

CREATE TABLE IF NOT EXISTS `ld_crmlog_import` (
    `id` int(20) NOT NULL AUTO_INCREMENT,
    `userid` int(20) NOT NULL,
    `status` varchar(200) NOT NULL,
    `module` varchar(100) DEFAULT NULL ,
    `importnum` Int(20) NOT NULL,
    `failedimportnum` int(20) DEFAULT NULL,
    `importresult` text(0) DEFAULT NULL,
    `duplicatefield` varchar(100) DEFAULT NULL,
    `importtype` varchar(200) DEFAULT NULL ,
    `starttime` datetime DEFAULT NULL,
    `finishtime` datetime DEFAULT NULL,
    `importfilename` text(0) DEFAULT NULL ,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
delimiter;

CREATE TABLE IF NOT EXISTS `ld_crmlog_export` (
    `id` int(20) NOT NULL AUTO_INCREMENT,
    `userid` int(20) NOT NULL,
    `status` varchar(200) NOT NULL,
    `module` varchar(100) DEFAULT NULL ,
    `exportnum` Int(20) NOT NULL,
    `exportresult` text(0) DEFAULT NULL,
    `starttime` datetime DEFAULT NULL,
    `finishtime` datetime DEFAULT NULL,
    `exporttype` text(0) DEFAULT NULL ,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
delimiter;

DROP EVENT IF EXISTS `autodelete_operationtionlogs_event`;
delimiter ||
CREATE EVENT `autodelete_operationtionlogs_event` ON SCHEDULE EVERY 1 DAY STARTS '2023-02-09 00:30:00' ON COMPLETION NOT PRESERVE ENABLE DO
call autodelete_operationtionlogs_procedure()
||
delimiter;

DROP PROCEDURE IF EXISTS `autodelete_operationtionlogs_procedure`;
delimiter ||
CREATE PROCEDURE `autodelete_operationtionlogs_procedure`(
)
BEGIN

	set @delete_month =(SELECT deploy_value from ld_systems_deploy where deploy_type = 468);
	DELETE FROM ld_crmlog_entity WHERE operationtime < DATE_SUB(NOW(), INTERVAL @delete_month MONTH);
	DELETE FROM ld_crmlog_create WHERE operationtime < DATE_SUB(NOW(), INTERVAL @delete_month MONTH);
	DELETE FROM ld_crmlog_edit WHERE operationtime < DATE_SUB(NOW(), INTERVAL @delete_month MONTH);
	DELETE FROM ld_crmlog_share WHERE operationtime < DATE_SUB(NOW(), INTERVAL @delete_month MONTH);
	DELETE FROM ld_crmlog_delete WHERE operationtime < DATE_SUB(NOW(), INTERVAL @delete_month MONTH);

END ||
delimiter;

call addtableIndex('ld_crmlog_entity','crmlog_module_operationtime_userid','module, operationtime, userid');
call addtableIndex('ld_crmlog_create','crmlog_module_operationtime_userid','module, operationtime, userid');
call addtableIndex('ld_crmlog_edit','crmlog_module_operationtime_userid','module, operationtime, userid');
call addtableIndex('ld_crmlog_share','crmlog_module_operationtime_userid','module, operationtime, userid');
call addtableIndex('ld_crmlog_delete','crmlog_module_operationtime_userid','module, operationtime, userid');
call addtableIndex('ld_crmlog_import','crmlog_module_operationtime_userid','module, starttime, userid');
call addtableIndex('ld_crmlog_export','crmlog_module_operationtime_userid','module, starttime, userid');
call addtableIndex('ld_crmlog_deletedrecords','crmlog_crmid','crmid');
delimiter;

