CREATE TABLE IF NOT EXISTS `ld_personnelfile` (
    `personnelfile_id` int(11) NOT NULL,
    `personnelfile_no` varchar(20) DEFAULT NULL,
    `personnelfile_name` varchar(50) ,
    `personnelfile_group` varchar(50) ,
    `personnelfile_position` varchar(50) ,
    `personnelfile_rank` varchar(20) ,
    `personnelfile_gender` varchar(20) ,
    `personnelfile_nation` varchar(20) ,
    `personnelfile_politicaloutlook` varchar(20) ,
    `personnelfile_idcard` varchar(20) ,
    `personnelfile_birthday` date ,
    `personnelfile_graduate` varchar(50) ,
    `personnelfile_major` varchar(50) ,
    `personnelfile_education` varchar(20) ,
    `personnelfile_contact` varchar(50) ,
    `personnelfile_mail` varchar(50) ,
    `personnelfile_marriage` varchar(20) ,
    `personnelfile_health` varchar(20) ,
    `personnelfile_emergencyname` varchar(50) ,
    `personnelfile_emergencycontact` varchar(50) ,
    `personnelfile_nativeplace` varchar(50) ,
    `personnelfile_registertype` varchar(20) ,
    `personnelfile_registeredresidence` varchar(50) ,
    `personnelfile_address` varchar(50) ,
    `personnelfile_description` text ,
    `personnelfile_status` varchar(20) ,
    `personnelfile_type` varchar(20) ,
    `personnelfile_probation` varchar(20) ,
    `personnelfile_joineddate` date ,
    `personnelfile_confirmdate` date ,
    `personnelfile_workdate` date ,
    `personnelfile_worklocation` varchar(50) ,
    `personnelfile_bank` varchar(50) ,
    `personnelfile_bankaccount` varchar(20) ,
    `personnelfile_probationsalary` decimal(25,8) ,
    `personnelfile_salary` decimal(25,8) ,
    `smownerid` Int(4) NOT NULL,
    `smcreatorid` Int(4),
    `createdtime` datetime ,
    `modifiedby` Int(4),
    `modifiedtime` datetime,
    `approvestatus` Varchar(50),
    `approvetime` Datetime,
    `approveby` Int(4),
    `currentapprover` text,
    `latestpushtime` Datetime,
    `Advance_stage` Varchar(100),
    `exchtime` Datetime,
    `exchmsg` text,
    `team_memberid` text,
    `tag` text,
    `Print_times` int(4),
    `approvesubmitter` int(4),
    `approveurgent` Varchar(100),
    `approveexpediting` Varchar(100) ,
    `Kis_id` Int(4) ,
    `Kis_no` Varchar(50) ,
    PRIMARY KEY (`personnelfile_id`)
    ) ENGINE = INNODB DEFAULT CHARSET = utf8;
delimiter;

CREATE TABLE IF NOT EXISTS `ld_personnelfilescf` (
    `personnelfile_id` int(11) NOT NULL,
    PRIMARY KEY (`personnelfile_id`)
    ) ENGINE = INNODB DEFAULT CHARSET = utf8;
delimiter;

