CREATE TABLE IF NOT EXISTS `ld_workreport_briefreport_detail` (
    `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id',
    `name` varchar(100) DEFAULT NULL COMMENT '简报名',
    `label_zh` varchar(100) DEFAULT NULL COMMENT '简报中文名',
    `label_en` varchar(100) DEFAULT NULL COMMENT '简报英文名',
    `is_default` varchar(20) DEFAULT NULL COMMENT '是否是预制简报',
    `presence` varchar(20) NOT NULL COMMENT '简报状态,是否启用',
    `sequence` int(11) NOT NULL COMMENT '排序',
    `delete` int(4) DEFAULT '0' COMMENT '是否被删除',
    `count_module` varchar(50) NOT NULL COMMENT '统计模块',
    `count_type` varchar(20) NOT NULL COMMENT '统计方式',
    `count_columnname` varchar(200) NOT NULL COMMENT '统计字段',
    `count_datarange` varchar(255) NOT NULL COMMENT '统计查看范围映射字段',
    `count_timerange` varchar(255) NOT NULL COMMENT '统计时间范围映射字段',
    `advft_criteria` text DEFAULT NULL COMMENT '查询条件',
    `advft_criteria_groups` text DEFAULT NULL COMMENT '查询条件组',
    `content_value` text DEFAULT NULL COMMENT '字段显示内容模版',
    PRIMARY KEY (`id`)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8;
delimiter;

SET @name= 'Leads';
SELECT tabid into @tabid from ld_tab where `name` = @name ;
SELECT fieldlabel into @modulezhname from ld_tranlabel where languagetype = 'zh' and trantable = 'ld_tab' and tabid = @tabid ;
SELECT fieldlabel into @moduleenname from ld_tranlabel where languagetype = 'en' and trantable = 'ld_tab' and tabid = @tabid ;
SELECT presence,sequence INTO @presence,@sequence FROM ld_workreport_showset WHERE type=@name AND belongtype ='component' ;
INSERT INTO ld_workreport_briefreport_detail(name,label_zh,label_en,is_default,presence,sequence,count_module,count_type,count_columnname,count_datarange,count_timerange,advft_criteria,advft_criteria_groups,content_value)SELECT @name,CONCAT('新增',@modulezhname),CONCAT('New ',@moduleenname),'yes',@presence,@sequence,'Leads','count','ld_leads.accountname','ld_leads:smownerid:assigned_user_id:Leads_fieldlabel:V','ld_leads:createdtime:createdtime:Leads_fieldlabel:DT','','','[var.leads_createdtime_Leads]  [var.leads_accountname_Leads]  [var.leads_contactname_Leads]' FROM DUAL WHERE NOT EXISTS(SELECT 1 FROM ld_workreport_briefreport_detail where name = @name);
delimiter;

SET @name= 'Accounts';
SELECT tabid into @tabid from ld_tab where `name` = @name ;
SELECT fieldlabel into @modulezhname from ld_tranlabel where languagetype = 'zh' and trantable = 'ld_tab' and tabid = @tabid ;
