set @tabid = (SELECT tabid from ld_tab where `name` = 'Accounts');
DELETE from ld_relatedlists where tabid = @tabid and `name` = '1' and related_tabid in
(SELECT tabid from ld_tab where FIND_IN_SET(`name`,'Questionnaire,WeChatUser,CustomTables,ShopSettings,BudgetChange,WorkReportList'));
delimiter;

update ld_customreportsql_column
    LEFT JOIN ld_customreport_total_column ON ld_customreportsql_column.report_id = ld_customreport_total_column.report_id AND ld_customreportsql_column.id = ld_customreport_total_column.`columns`
    set ld_customreportsql_column.column_label = ld_customreport_total_column.chart_column_name
WHERE IFNULL(ld_customreport_total_column.chart_column_name,'') <> '' AND ld_customreport_total_column.chart_column_name <> '';
delimiter;

