FROM DUAL WHERE NOT EXISTS(SELECT 1 FROM ld_homestuffdetail WHERE stufflabel='SalesRanking_Invoice' and compute_module='Invoice' and stuffid=33);

INSERT INTO ld_homestuffdetail(stuffid,stufflabel,stufflabeltype,compute_columns,compute_type,stufflabel_zh,stufflabel_en,daterange,viewrange,is_default,compute_module,advance_demand,advance_demand_groups,topnumber)
SELECT 33,'SalesRanking_OutboundOrder','fixedstr','ld_outboundorder.total','sum','出库金额','OutboundOrder Amount','','ld_outboundorder:smownerid:assigned_user_id:OutboundOrder_fieldlabel:V','yes','OutboundOrder','','',0
FROM DUAL WHERE NOT EXISTS(SELECT 1 FROM ld_homestuffdetail WHERE stufflabel='SalesRanking_OutboundOrder' and compute_module='OutboundOrder' and stuffid=33);
end if ;
end ||
