drop PROCEDURE if EXISTS delete_wrong_advancenode;
delimiter ||
create PROCEDURE delete_wrong_advancenode
(
)
BEGIN
	set @pot_presence = (SELECT presence from ld_tab where `name` = 'Potentials');

	set @fieldname = 'status';set @frommodule = 'Leads';
	IF @pot_presence = 1 or @pot_presence = 5 then
		set @delete_name = '升级到客户和销售机会';
		set @stageid = (SELECT stageid from ld_advanceprocess where frommodule = @frommodule and fieldname = @fieldname and stagename = @delete_name);
		set @nodeid = (SELECT nodeid from ld_advanceprocess where stageid = @stageid);
		set @new_childid = (SELECT childid from ld_advanceprocess where stageid = @stageid);
		UPDATE ld_advanceprocess set childid = @new_childid where childid = @nodeid and frommodule = @frommodule and fieldname = @fieldname;
		DELETE from ld_advanceprocess where stageid = @stageid;
	end if;

	set @acc_presence = (SELECT presence from ld_tab where `name` = 'Accounts');

	IF @acc_presence = 1 or @acc_presence = 5 then
		set @delete_name = '升级到客户';
		set @stageid = (SELECT stageid from ld_advanceprocess where frommodule = @frommodule and fieldname = @fieldname and stagename = @delete_name);
		set @nodeid = (SELECT nodeid from ld_advanceprocess where stageid = @stageid);
		set @new_childid = (SELECT childid from ld_advanceprocess where stageid = @stageid);
		UPDATE ld_advanceprocess set childid = @new_childid where childid = @nodeid and frommodule = @frommodule and fieldname = @fieldname;
		DELETE from ld_advanceprocess where stageid = @stageid;
	end if;

end ||
delimiter;

call delete_wrong_advancenode();
drop PROCEDURE if EXISTS delete_wrong_advancenode;
delimiter;

