)
SELECT
        @maxtabid + 1,@modulename,0 ,@maxtabsequence + 1,@modulename,null,1,'yes'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM ld_tab WHERE NAME = @modulename);


