INSERT INTO ld_tranlabel (
    languagetype,trantable,tabid,relateid,fieldlabel)
SELECT
    'zh','ld_tab' ,@tabid ,@tabid,'竞争对手'
FROM DUAL WHERE NOT EXISTS (
        SELECT 1 FROM ld_tranlabel WHERE tabid =@tabid
                                     AND relateid =@tabid
                                     AND languagetype = 'zh'
                                     AND trantable = 'ld_tab'
    );

