DROP PROCEDURE IF EXISTS `ldcrm_add_tabindex_20240308`;
delimiter ||
CREATE  PROCEDURE `ldcrm_add_tabindex_20240308`(
)
BEGIN

		DECLARE tmp_execsql TEXT DEFAULT '';

		DECLARE MYCUSOR CURSOR FOR 
			SELECT
				execsql
			FROM (
				SELECT
					CONCAT("CALL addtableIndex('",tablename,"','",columnname,"','",columnname,"');") AS execsql
				FROM ld_field
				WHERE columnname IN ('deleted','smownerid','smcreatorid','createdtime','modifiedtime','accountid','approvestatus')
					AND IFNULL(tablename,'')<>''
					AND IFNULL(columnname,'')<>''
					AND tablename NOT IN ('ld_reminds')
				UNION
				SELECT
					CONCAT("CALL addtableIndex('",TABLE_NAME,"','",COLUMN_NAME,"','",COLUMN_NAME,"');") AS execsql
				FROM information_schema.COLUMNS
				WHERE TABLE_SCHEMA=DATABASE()
					AND COLUMN_NAME='parent_lineitem_id'
			) a
			WHERE execsql LIKE 'CALL addtableIndex(%'
			ORDER BY execsql;
			

		DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_execsql = NULL;

		IF (SELECT COUNT(1) FROM ld_crmentity WHERE setype<>'Reminds')<2000 THEN
			OPEN MYCUSOR; 
			FETCH MYCUSOR INTO tmp_execsql;
			
			WHILE(tmp_execsql IS NOT NULL) DO
				SET @tmp_execsql=tmp_execsql;
				PREPARE mystmt FROM @tmp_execsql;
				EXECUTE mystmt;
				DEALLOCATE PREPARE mystmt;

				FETCH MYCUSOR INTO tmp_execsql;
			END WHILE;
			CLOSE MYCUSOR;

		END IF;

end ||
delimiter;

CALL ldcrm_add_tabindex_20240308();
